import numpy as np

grid_np = np.array([list(map(int, line.split())) for line in original_grid_str.strip().split('\n')])

def check_palindrome(grid):
    """Check if every row is a palindrome"""
    return all(np.array_equal(row, row[::-1]) for row in grid)

def transform_90cw(grid):
    return np.rot90(grid, k=-1)

def transform_90ccw(grid):
    return np.rot90(grid, k=1)

def transform_v_flip(grid):
    return np.flipud(grid)

def transform_h_flip(grid):
    return np.fliplr(grid)

def transform_180(grid):
    return np.rot90(grid, k=2)

candidates = {
    'original': grid_np.copy(),
    '90_cw': transform_90cw(grid_np),
    '90_ccw': transform_90ccw(grid_np),
    'v_flip': transform_v_flip(grid_np),
    'h_flip': transform_h_flip(grid_np),
    '180': transform_180(grid_np),
}

for name, c in candidates.items():
    is_all_pal = check_palindrome(c)
    n_pal = sum(1 for i in range(len(c)) if np.array_equal(c[i], c[i][::-1]))
    print(f"{name}: all_rows_pal={is_all_pal}, n_palindromes={n_pal}")

